/**
 * RegimeCard.js - Market Regime Detection Display
 * With glowing active badges
 */

import React from 'react';
import { motion } from 'framer-motion';

const RegimeCard = ({ regime }) => {
  if (!regime) return null;

  const regimes = [
    {
      id: 0,
      name: 'CALM',
      icon: '✅',
      description: 'Low Volatility',
      color: '#10b981',
      bgColor: 'rgba(16, 185, 129, 0.1)',
    },
    {
      id: 1,
      name: 'TRENDING',
      icon: '📈',
      description: 'Uptrend Detected',
      color: '#3b82f6',
      bgColor: 'rgba(59, 130, 246, 0.1)',
    },
    {
      id: 2,
      name: 'VOLATILE',
      icon: '⚠️',
      description: 'High Risk Zone',
      color: '#ef4444',
      bgColor: 'rgba(239, 68, 68, 0.1)',
    },
  ];

  return (
    <div className="glass-card regime-card-premium">
      <h3 className="section-title">
        <span className="icon">🎯</span>
        <span>Market Regime Detection</span>
      </h3>

      <div className="regime-badges-container">
        {regimes.map((r, index) => {
          const isActive = r.id === regime.regime_id;

          return (
            <motion.div
              key={r.id}
              className={`regime-badge-item ${isActive ? 'active' : ''}`}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.4, delay: index * 0.1 }}
              whileHover={{ scale: isActive ? 1.05 : 1.02 }}
              style={{
                background: isActive ? r.bgColor : 'rgba(255, 255, 255, 0.02)',
                borderColor: isActive ? r.color : 'rgba(255, 255, 255, 0.1)',
              }}
            >
              <div className="regime-icon">{r.icon}</div>
              <div className="regime-name">{r.name}</div>
              <div className="regime-desc">{r.description}</div>

              {isActive && (
                <motion.div
                  className="regime-glow"
                  animate={{
                    opacity: [0.5, 1, 0.5],
                    scale: [1, 1.1, 1],
                  }}
                  transition={{
                    duration: 2,
                    repeat: Infinity,
                  }}
                  style={{
                    boxShadow: `0 0 30px ${r.color}`,
                  }}
                />
              )}
            </motion.div>
          );
        })}
      </div>

      <motion.div 
        className="regime-details"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.5, delay: 0.5 }}
      >
        <div className="regime-detail-row">
          <span className="detail-label">Current Regime:</span>
          <span className="detail-value">{regime.regime_name}</span>
        </div>
        <div className="regime-detail-row">
          <span className="detail-label">Regime Confidence:</span>
          <span className="detail-value">{(regime.confidence * 100).toFixed(1)}%</span>
        </div>
        <div className="regime-detail-row">
          <span className="detail-label">Adjusted Confidence:</span>
          <span className="detail-value">{(regime.adjusted_model_confidence * 100).toFixed(1)}%</span>
        </div>
      </motion.div>

      <div className="regime-description">
        {regime.description}
      </div>

      <div className="feature-tip">
        <span className="tip-icon">💡</span>
        <span className="tip-text">
          Predictions adjust confidence based on market volatility
        </span>
      </div>
    </div>
  );
};

export default RegimeCard;
